using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> typeInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {typeInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), typeInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): check-without-throwing ---
// Person metadata is available via the default resolver:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? personInfo))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded – type: {personInfo!.Type.Name}");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Person> returned false");
}

// For a type whose metadata might NOT be resolvable (e.g. with a
// restricted resolver), TryGetTypeInfo returns false instead of throwing.
var restricted = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
        .WithAddedModifier(ti =>
        {
            // Only allow Person; reject everything else.
            if (ti.Type != typeof(Person))
                throw new NotSupportedException($"No metadata for {ti.Type.Name}");
        })
};

if (restricted.TryGetTypeInfo<int>(out JsonTypeInfo<int>? intInfo))
{
    Console.WriteLine($"TryGetTypeInfo<int> succeeded – type: {intInfo!.Type.Name}");
}
else
{
    Console.WriteLine("TryGetTypeInfo<int> returned false (no exception thrown)");
}

// Record used in the demo
public record Person(string Name, int Age);

